for name, slug, img in polish_forms:
    lines.append(f'  {{ name: "{name}", slug: "{slug}", category: "Формы для плитки", categorySlug: "formy-dlya-plitki", image: "{img}", subcategory: "Альфа (Польша)", country: "Польша", manufacturer: "ALPHA", availability: "В наличии" }},')

